{
  "critique": [
    {
      "design": "r1A",
      "good": "The identifying and audit fields are easy to scan, all headers stay on one line, and the long package identifier and notes wrap without mid-word splits. Rows remain distinct despite the taller entries.",
      "problems": "The right side of Notes requires horizontal scrolling, so some context is missing at first sight.",
      "cause": "Notes needs 273px to keep its longest unbreakable string intact; together with the 190px Package column, that brings the table to 798px."
    },
    {
      "design": "r1B",
      "good": "The audit columns retain their clear alignment, and the table comes close to fitting the viewport without adding row height.",
      "problems": "The long string in Notes splits mid-word, making it harder to read or copy accurately. Some Notes content still requires scrolling.",
      "cause": "At 245px, Notes has only 224px of text space, less than the 252px required by its longest unbreakable string. Package at 168px is sufficient for its longest unbreakable segment."
    },
    {
      "design": "r1C",
      "good": "Headers and identifiers remain intact, and the audit fields are well separated. Notes avoids mid-word splits.",
      "problems": "The wider Package column does not reduce the long row's height, while more of Notes falls beyond the viewport.",
      "cause": "Increasing Package to 220px adds 30px to the table compared with r1A without changing the displayed row heights; the table overflows by 108px."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "intact-compact",
      "widths": [168, 112, 98, 124, 273],
      "change": "Use r1B's compact Package width and r1A's Notes width. This preserves unbroken strings while reducing overflow to 56px."
    },
    {
      "name": "viewport-fit",
      "widths": [168, 112, 98, 124, 217],
      "change": "Fit the full table within 719px while keeping the identifying and audit fields intact. The narrower Notes column will split its longest string and may increase row height, but eliminates horizontal scrolling."
    }
  ]
}
